edits.anchor:
function extRowPlate(s,x,y,R){
  var w=hudRawW(s)+LH(24)*R, h=LH(26)*R, px=Math.round(x-w/2), py=Math.round(y-LH(19)*R);
  hudPanel(px,py,w,h,0.9,true);
  return {x:px,y:py,w:w,h:h};
}

edits.replacement:
function extRowPlate(s,x,y,R,minW){
  // v32.xx (cw-hostcol), the critic on screen 37: the plate was a narrower pill touching the banner. It takes the banner width (minW) and sits 8 px under it, one column.
  var w=Math.max(hudRawW(s)+LH(24)*R,minW||0), h=LH(22)*R, px=Math.round(x-w/2), py=Math.round(y-LH(16)*R);
  hudPanel(px,py,w,h,0.9,true);
  return {x:px,y:py,w:w,h:h};
}

check:
{v:'VER',what:'the hostiles plate is as wide as the banner above it with a gap under the banner (critic 37)',
 run:function(){
   if(typeof extRowPlate!=='function') return 'no extRowPlate';
   var s='1 HOSTILE CLOSING IN', r, f=ctx.font;
   ctx.save(); ctx.font=hudFS(TYPE.label);
   try{ r=extRowPlate(s,960,900,1,600); }finally{ ctx.restore(); ctx.font=f; }
   if(!r||Math.round(r.w)<600) return 'the plate ignores the banner width: '+(r&&r.w);
   var src=String(drawHUD);
   if(src.indexOf('_exBelt-LH(62)')<0) return 'the banner did not move up for the gap';
   if(src.indexOf('extRowPlate(_exH,W/2,_exRow,_exR,_exBW)')<0) return 'drawHUD does not pass the banner width';
   return null;
 }},
